const item = ($input.first() && $input.first().json) || {};

function cleanField(val, fallback) {
  if (val === undefined || val === null || String(val).trim() === '') {
    return fallback;
  }
  return String(val).trim();
}

function toArray(v) {
  if (!v) return [];
  return String(v)
    .split(/[\n,;]+/)
    .map(s => s.trim())
    .filter(s => s.length > 0);
}

// Strictly use user input with no synthetic topic bleed
const title = cleanField(item.title, 'Food & Tourism: How the Caribbean Can Capture More Value from Farm-to-Table Experiences');
const mainQuestion = cleanField(item.main_question, 'How can Caribbean destinations capture more local economic value from farm-to-table tourism experiences?');
const objective = cleanField(item.objective, 'Assess agricultural linkages, food import substitution, and local economic retention models in Caribbean hospitality.');
const questions = cleanField(item.questions, '1. What proportion of hotel food demand is imported vs locally sourced across Caribbean markets?\n2. What are key supply chain, quality, and cold-chain barriers for local farmers?\n3. What successful farm-to-table initiatives exist (e.g. ALEX Jamaica, Bellemont Farm, Sandals)?\n4. How can agritourism culinary experiences maximize local economic retention?\n5. What policy incentives and financing instruments can accelerate hotel-farmer commercial contracts?');

let geographyArr = toArray(item.geography);
const usedCaribbeanDefault = geographyArr.length === 0;
if (usedCaribbeanDefault) {
  geographyArr = ['Jamaica', 'Barbados', 'Saint Lucia', 'Dominican Republic', 'Guadeloupe', 'Martinique', 'Trinidad & Tobago', 'Bahamas', 'Antigua & Barbuda', 'Aruba', 'Curacao'];
}

const reportLanguage = (item.report_language && String(item.report_language).trim()) || 'English';
const dateRange = cleanField(item.date_range, '2015-2025');
const priorityThemes = cleanField(item.priority_themes, 'Agritourism, Food Import Substitution, Cold-Chain Logistics, Procurement Linkages, Value Retention, SIDS Economics');
const preferredSourceTypes = cleanField(item.preferred_source_types, 'Tier 1 & Tier 2: Multilateral PDFs, Government Statistical Bulletins, Central Banks, Regional Development Banks');
const instructions = cleanField(item.instructions, '');

return [{
  json: {
    title,
    main_question: mainQuestion,
    objective,
    questions,
    geography_arr: geographyArr,
    used_caribbean_default: usedCaribbeanDefault,
    date_range: dateRange,
    report_language: reportLanguage,
    priority_themes: priorityThemes,
    preferred_source_types: preferredSourceTypes,
    instructions: instructions
  }
}];

